import { useMemo, useState } from 'react';
import {
  Table,
  TableHead,
  TableBody,
  TableRow,
  TableCell,
  Badge,
  Pagination,
  Stack,
} from '@jinx-ui/react';

const PAGE_SIZE = 10;

export type User = {
  id: string | number;
  name: string;
  role: string;
  status: 'active' | 'disabled';
};

type UsersTableProps = {
  users: User[];
};

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
      <Table>
        <TableHead>
          <TableRow>
            <TableCell as="th">Имя</TableCell>
            <TableCell as="th">Роль</TableCell>
            <TableCell as="th">Статус</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {rows.map((user) => (
            <TableRow key={user.id}>
              <TableCell>{user.name}</TableCell>
              <TableCell>{user.role}</TableCell>
              <TableCell>
                <Badge tone={user.status === 'active' ? 'success' : 'neutral'}>
                  {user.status === 'active' ? 'Активен' : 'Отключён'}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>

      <Pagination page={currentPage} pageCount={pageCount} onPageChange={setPage} />
    </Stack>
  );
}

